// Turns the incoming batch into stable dedup keys and builds the two Supabase REST
// URLs the next nodes call. Config lives here so there is a single place to edit.
const SUPABASE_URL = '';        // TODO: https://<project>.supabase.co
const PREVIEW_LIMIT = 200;      // never store more of the payload than this

const input = $input.first().json || {};
const source = String(input.source || '').trim();
const keyField = String(input.key_field || '').trim();
const items = Array.isArray(input.items) ? input.items : [];

if (!source) throw new Error('source is required');
if (!keyField) throw new Error('key_field is required');
if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Build keys"');

const enc = new TextEncoder();
const sha256 = async (s) => {
  const buf = await crypto.subtle.digest('SHA-256', enc.encode(s));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
};

const keys = [];
for (const item of items) {
  const raw = item === null || item === undefined ? '' : item[keyField];
  if (raw === undefined || raw === null || String(raw) === '') {
    throw new Error('item is missing key_field "' + keyField + '": ' + JSON.stringify(item).slice(0, 120));
  }
  const value = String(raw);
  keys.push({
    hash: await sha256(source + ':' + value),
    value,
    item,
    preview: JSON.stringify(item).slice(0, PREVIEW_LIMIT),
  });
}

// Deduplicate inside the batch itself: the same key twice in one call is one item.
const seenInBatch = new Set();
const unique = keys.filter((k) => (seenInBatch.has(k.hash) ? false : seenInBatch.add(k.hash)));
const duplicatesInBatch = keys.length - unique.length;

const base = SUPABASE_URL.replace(/\/+$/, '');
const hashList = unique.map((k) => '"' + k.hash + '"').join(',');

return [{
  json: {
    source,
    keyField,
    total: items.length,
    duplicatesInBatch,
    keys: unique,
    // PostgREST: hash=in.("a","b"). An empty batch must not produce in.() which is invalid.
    selectUrl: base + '/rest/v1/seen_items?select=hash&hash=in.(' + (hashList || '"__none__"') + ')',
    insertUrl: base + '/rest/v1/seen_items',
  },
}];

// Subtracts the hashes the database already knows from the batch.
const built = $('Build keys').first().json;
const seen = new Set(
  $input.all().map((i) => i.json && i.json.hash).filter((h) => typeof h === 'string')
);

const fresh = built.keys.filter((k) => !seen.has(k.hash));
const now = new Date().toISOString();

return [{
  json: {
    source: built.source,
    hasNew: fresh.length > 0,
    new_items: fresh.map((k) => k.item),
    skipped: built.total - fresh.length,
    duplicatesInBatch: built.duplicatesInBatch,
    // One batch insert, never one call per item.
    rows: fresh.map((k) => ({
      hash: k.hash,
      source: built.source,
      first_seen_at: now,
      payload_preview: k.preview,
    })),
  },
}];

// Both branches converge here, so the caller always gets the same shape whether or
// not an insert happened.
const d = $('Diff against seen').first().json;
return [{
  json: {
    source: d.source,
    new_items: d.new_items,
    skipped: d.skipped,
    duplicates_in_batch: d.duplicatesInBatch,
  },
}];
